const ruta = ["Almagro", "Palermo", "Belgrano"];
console.log("índices 0 y 2:", ruta[0], "y", ruta[2]);
console.log("índice 3 (no existe):", ruta[3], "| largo:", ruta.length);

const nuevoLargo = ruta.push("Núñez");      // agrega al final y devuelve el largo nuevo
console.log("push →", nuevoLargo, ruta);

const sacada = ruta.pop();                  // saca del final y devuelve lo que sacó
console.log("pop →", sacada, ruta);

ruta.unshift("Depósito");                   // agrega al principio: todo se corre un lugar
console.log("unshift →", ruta);

const primera = ruta.shift();               // saca del principio: todo vuelve a correrse
console.log("shift →", primera, ruta);

// splice(desde, cuántos borrar, ...lo que se inserta): modifica la lista original
ruta.splice(1, 0, "Urgente");               // inserta en el índice 1 sin borrar nada
console.log("splice insertar →", ruta);
const borradas = ruta.splice(2, 1);         // borra 1 elemento desde el índice 2
console.log("splice borrar →", borradas, ruta);

// slice(desde, hasta) NO modifica: devuelve una copia del tramo
const tramo = ruta.slice(0, 2);
console.log("slice →", tramo, "| la original sigue:", ruta);

// Mutar un elemento por su índice
ruta[0] = "Almagro (cerrado)";
