const kms = [12, 7, 25, 3];

// 1) Con índice: vos controlás la posición (y también el error por uno)
let total = 0;
for (let i = 0; i < kms.length; i++) {
  total += kms[i];
}
console.log("total con índice:", total);

// 2) for...of: te da cada elemento, sin índice
let mayor = kms[0];
for (const km of kms) {
  if (km > mayor) mayor = km;
}
console.log("tramo más largo:", mayor);

// 3) Si necesitás las dos cosas, entries() entrega pares [índice, elemento]
for (const [i, km] of kms.entries()) {
  console.log("parada", i + 1, "→", km, "km");
}

// El error por uno: <= recorre un lugar de más
let mal = 0;
for (let i = 0; i <= kms.length; i++) {
  mal += kms[i];                 // la última vuelta suma kms[4], que no existe
}
console.log("total con <=:", mal);

