#include <stdio.h>

int main(void) {
    int kms[4] = {12, 7, 25, 3};
    int indice = 4;                 // un lugar más allá del final
    printf("kms[%d] = %d\n", indice, kms[indice]);
    return 0;
}

// Typed arrays: elementos de UN solo tipo y tamaño fijo, pegados en memoria
const kms = new Int32Array([12, 7, 25, 3]);
console.log("bytes por elemento:", kms.BYTES_PER_ELEMENT);
console.log("elementos:", kms.length, "| bytes en total:", kms.byteLength);

// El mismo bloque de 16 bytes visto como bytes sueltos
// (en un procesador little-endian, el orden de bytes del día de la RAM)
const bytes = new Uint8Array(kms.buffer);
console.log("los 16 bytes:", Array.from(bytes));

// Tamaño fijo: no hay push, y escribir fuera del largo no hace nada
kms[10] = 99;
console.log("kms[10]:", kms[10], "| largo:", kms.length, "| tiene push:", typeof kms.push);

// Cada tipo tiene su rango: pasarse da la vuelta, como en el complemento a dos
const chico = new Uint8Array([250]);
chico[0] = chico[0] + 10;
console.log("Uint8: 250 + 10 =", chico[0]);

const firmado = new Int8Array([127]);
firmado[0] = firmado[0] + 1;
console.log("Int8: 127 + 1 =", firmado[0]);

const sujeto = new Uint8ClampedArray([250]);
sujeto[0] = sujeto[0] + 10;
console.log("Uint8Clamped: 250 + 10 =", sujeto[0]);

// Un tipo de coma flotante guarda lo que le cabe
const f32 = new Float32Array([0.1]);
console.log("Float32 guarda 0.1 como:", f32[0], "| un número común de JS:", 0.1);

// Un array común puede mezclar tipos; uno tipado convierte
const comun = [12, "7", true];
const tipado = new Int32Array([12, "7", true]);
console.log("común:", comun, "| tipado:", Array.from(tipado));

// La trampa de sort(): sin ayuda, ordena como TEXTO
const kms = [100, 25, 9, 3, 12];
console.log("sort() solo:", [...kms].sort());

// Por qué: se compara carácter por carácter, y "1" va antes que "2", que "3" y que "9"
console.log('"100" < "25":', "100" < "25", '| "12" < "9":', "12" < "9");

// La solución: una función que compara de a dos y devuelve negativo, cero o positivo
console.log("con a - b:", [...kms].sort((a, b) => a - b));
console.log("al revés:   ", [...kms].sort((a, b) => b - a));

// sort() MODIFICA la lista original (por eso arriba copiamos con [...kms])
const original = [3, 1, 2];
const ordenada = original.sort((a, b) => a - b);
console.log("original después de sort:", original, "| es el mismo array:", original === ordenada);

// Un typed array, en cambio, ordena como números sin pedirlo
console.log("Int32Array.sort():", Array.from(new Int32Array(kms).sort()));

// Con texto también hay una trampa: ordena por código, no por el alfabeto del español
const barrios = ["Núñez", "Almagro", "Ñandú", "Zárate", "Álamo"];
console.log("sort() solo:", [...barrios].sort());
console.log("con localeCompare:", [...barrios].sort((a, b) => a.localeCompare(b, "es")));

